xml.Script:
        clYellow  := 'FFFF00';
        clBlue    := '0000A0';
        clRed     := 'FF0000';
        clGreen   := '008000';
        clViolett := '800080';
        clCyan    := '00DCB4';
        clWhite   := 'FFFFFF';
        clBlack   := '222222';

        for i := 0 to 19 do
            Colors[i] := -1;

        Colors[ 0] := clViolett;
        Colors[ 5] := clCyan;
        Colors[15] := clRed;
        Colors[17] := clBlue;
        Colors[18] := clGreen;

        R := 0.7;
        include 'Figures\Scripts\Icosahedron_Coordinates.inc';

        jumAngle := Arcsin(1/4) + Pi/6;
